static int checks, failures;
#define CHECK(condition)                                                                    \
    do {                                                                                    \
        checks++;                                                                           \
        if (!(condition)) {                                                                 \
            failures++;                                                                     \
            fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #condition);            \
        }                                                                                   \
    } while (0)

static void sleep_ms(int ms) {
    struct timespec t = {ms / 1000, (long)(ms % 1000) * 1000000L};
    nanosleep(&t, NULL);
}

/* ---- The test server ---- */

typedef struct server {
    int listener, port, other_port;
    SSL_CTX *tls;
    pthread_t thread;
    atomic_int stop, connections, served;
} server;

typedef struct connection {
    server *owner;
    int fd;
    SSL *ssl;
} connection;

static int conn_read(connection *c, char *buffer, int size) {
    return c->ssl ? SSL_read(c->ssl, buffer, size) : (int)recv(c->fd, buffer, (size_t)size, 0);
}

static void conn_write(connection *c, const char *data, size_t length) {
    while (length) {
        int sent = c->ssl ? SSL_write(c->ssl, data, (int)length) : (int)send(c->fd, data, length, MSG_NOSIGNAL);
        if (sent <= 0) return;
        data += sent;
        length -= (size_t)sent;
    }
}

static void respond(connection *c, int head, int status, const char *extra, const char *body, size_t length) {
    char header[1024];
    int n = snprintf(header, sizeof header, "HTTP/1.1 %d Test\r\nContent-Length: %zu\r\nConnection: close\r\n%s\r\n",
                     status, length, extra ? extra : "");
    conn_write(c, header, (size_t)n);
    if (!head && length) conn_write(c, body, length);
}

/* An answer whose length is not known in advance: its head, then pieces. */
static void stream_open(connection *c) {
    static const char head[] = "HTTP/1.1 200 Test\r\nTransfer-Encoding: chunked\r\nContent-Type: text/plain\r\nConnection: close\r\n\r\n";
    conn_write(c, head, sizeof head - 1);
}
static void stream_piece(connection *c, const char *data, size_t length) {
    char size[24];
    int n = snprintf(size, sizeof size, "%zx\r\n", length);
    conn_write(c, size, (size_t)n);
    conn_write(c, data, length);
    conn_write(c, "\r\n", 2);
}
static void stream_wait(connection *c, int ms) {
    for (int waited = 0; waited < ms && !atomic_load(&c->owner->stop); waited += 10) sleep_ms(10);
}

static void serve(connection *c) {
    enum { REQUEST_MAX = 1 << 17 };
    char *buffer = malloc(REQUEST_MAX);
    size_t used = 0;
    char *end = NULL;
    while (!end && used < REQUEST_MAX - 1) {
        int got = conn_read(c, buffer + used, (int)(REQUEST_MAX - 1 - used));
        if (got <= 0) break;
        used += (size_t)got;
        buffer[used] = 0;
        end = strstr(buffer, "\r\n\r\n");
    }
    if (!end) {
        free(buffer);
        return;
    }
    size_t header_length = (size_t)(end - buffer) + 4, content_length = 0;
    const char *field = strcasestr(buffer, "\r\nContent-Length:");
    if (field && field < end) content_length = (size_t)strtoul(field + 17, NULL, 10);
    while (used < header_length + content_length && used < REQUEST_MAX - 1) {
        int got = conn_read(c, buffer + used, (int)(REQUEST_MAX - 1 - used));
        if (got <= 0) break;
        used += (size_t)got;
    }
    char method[16] = "", path[256] = "";
    sscanf(buffer, "%15s %255s", method, path);
    int head = !strcmp(method, "HEAD");
    atomic_fetch_add(&c->owner->served, 1);
    char extra[512];
    int number = 0, gap = 0;
    if (sscanf(path, "/stream/%d/%d", &number, &gap) == 2) {
        /* `number` pieces, one every `gap` milliseconds, then the end. */
        stream_open(c);
        for (int i = 0; i < number && !atomic_load(&c->owner->stop); i++) {
            int n = snprintf(extra, sizeof extra, "piece-%d\n", i);
            stream_piece(c, extra, (size_t)n);
            stream_wait(c, gap);
        }
        conn_write(c, "0\r\n\r\n", 5);
    } else if (sscanf(path, "/stall/%d", &number) == 1) {
        /* One piece, then silence for `number` milliseconds. */
        stream_open(c);
        stream_piece(c, "first\n", 6);
        stream_wait(c, number);
        conn_write(c, "0\r\n\r\n", 5);
    } else if (sscanf(path, "/flood/%d", &number) == 1) {
        char *body = malloc((size_t)number + 1);
        memset(body, 'y', (size_t)number);
        stream_open(c);
        stream_piece(c, body, (size_t)number);
        conn_write(c, "0\r\n\r\n", 5);
        free(body);
    } else if (!strcmp(path, "/stream-moved")) {
        respond(c, head, 302, "Location: /stream/3/20\r\n", "moved", 5);
    } else if (!strcmp(path, "/stream-refused")) {
        respond(c, head, 503, NULL, "refused", 7);
    } else if (!strcmp(path, "/hello")) {
        respond(c, head, 200, "X-Test: yes\r\nX-Two:   spaced value  \r\nSet-Cookie: sid=abc; Path=/\r\n", "hello", 5);
    } else if (!strcmp(path, "/echo")) {
        /* The request back as the body: its head, a blank line, its body. */
        respond(c, head, 200, "Content-Type: application/octet-stream\r\n", buffer, used);
    } else if (sscanf(path, "/redirect/%d", &number) == 1) {
        if (number > 0) {
            snprintf(extra, sizeof extra, "Location: /redirect/%d\r\n", number - 1);
            respond(c, head, 302, extra, "moved", 5);
        } else {
            respond(c, head, 200, NULL, "landed", 6);
        }
    } else if (sscanf(path, "/r%d", &number) == 1 && number >= 301 && number <= 308) {
        respond(c, head, number, "Location: /echo\r\n", "moved", 5);
    } else if (!strcmp(path, "/loop")) {
        respond(c, head, 302, "Location: /loop\r\n", "", 0);
    } else if (!strcmp(path, "/cross")) {
        snprintf(extra, sizeof extra, "Location: http://127.0.0.1:%d/echo\r\n", c->owner->other_port);
        respond(c, head, 302, extra, "", 0);
    } else if (!strcmp(path, "/elsewhere")) {
        respond(c, head, 302, "Location: ftp://127.0.0.1/file\r\n", "", 0);
    } else if (!strcmp(path, "/nowhere")) {
        respond(c, head, 302, NULL, "no location", 11);
    } else if (sscanf(path, "/slow/%d", &number) == 1) {
        for (int waited = 0; waited < number && !atomic_load(&c->owner->stop); waited += 10) sleep_ms(10);
        respond(c, head, 200, NULL, "slow", 4);
    } else if (sscanf(path, "/big/%d", &number) == 1) {
        char *body = malloc((size_t)number + 1);
        memset(body, 'x', (size_t)number);
        respond(c, head, 200, NULL, body, (size_t)number);
        free(body);
    } else if (!strcmp(path, "/gzip")) {
        respond(c, head, 200, "Content-Encoding: gzip\r\nContent-Type: text/plain\r\n", (const char *)gzip_bytes, sizeof gzip_bytes);
    } else if (!strcmp(path, "/empty")) {
        respond(c, head, 204, NULL, "", 0);
    } else if (!strcmp(path, "/manyheaders")) {
        char *many = malloc(600 * 16 + 1);
        size_t at = 0;
        for (int i = 0; i < 600; i++) at += (size_t)sprintf(many + at, "X-H%03d: v\r\n", i);
        char header[128];
        int n = snprintf(header, sizeof header, "HTTP/1.1 200 Test\r\nContent-Length: 0\r\nConnection: close\r\n");
        conn_write(c, header, (size_t)n);
        conn_write(c, many, at);
        conn_write(c, "\r\n", 2);
        free(many);
    } else {
        respond(c, head, 404, NULL, "not found", 9);
    }
    free(buffer);
}

static void *connection_thread(void *argument) {
    connection *c = argument;
    int ready = 1;
    if (c->owner->tls) {
        c->ssl = SSL_new(c->owner->tls);
        SSL_set_fd(c->ssl, c->fd);
        ready = SSL_accept(c->ssl) == 1;
    }
    if (ready) serve(c);
    if (c->ssl) {
        if (ready) SSL_shutdown(c->ssl);
        SSL_free(c->ssl);
    }
    shutdown(c->fd, SHUT_RDWR);
    close(c->fd);
    atomic_fetch_sub(&c->owner->connections, 1);
    free(c);
    ERR_clear_error();
    return NULL;
}

static void *accept_thread(void *argument) {
    server *s = argument;
    while (!atomic_load(&s->stop)) {
        struct pollfd wait = {s->listener, POLLIN, 0};
        if (poll(&wait, 1, 50) <= 0) continue;
        int fd = accept(s->listener, NULL, NULL);
        if (fd < 0) continue;
        connection *c = calloc(1, sizeof *c);
        c->owner = s;
        c->fd = fd;
        atomic_fetch_add(&s->connections, 1);
        pthread_t thread;
        pthread_attr_t attributes;
        pthread_attr_init(&attributes);
        pthread_attr_setdetachstate(&attributes, PTHREAD_CREATE_DETACHED);
        if (pthread_create(&thread, &attributes, connection_thread, c)) {
            close(fd);
            free(c);
            atomic_fetch_sub(&s->connections, 1);
        }
        pthread_attr_destroy(&attributes);
    }
    return NULL;
}

static int server_start(server *s, const char *certificate, const char *key) {
    memset(s, 0, sizeof *s);
    if (certificate) {
        s->tls = SSL_CTX_new(TLS_server_method());
        if (!s->tls || SSL_CTX_use_certificate_file(s->tls, certificate, SSL_FILETYPE_PEM) != 1 ||
            SSL_CTX_use_PrivateKey_file(s->tls, key, SSL_FILETYPE_PEM) != 1)
            return -1;
    }
    s->listener = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in address = {0};
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);   /* this machine only */
    socklen_t length = sizeof address;
    if (s->listener < 0 || bind(s->listener, (struct sockaddr *)&address, sizeof address) ||
        listen(s->listener, 64) || getsockname(s->listener, (struct sockaddr *)&address, &length))
        return -1;
    s->port = ntohs(address.sin_port);
    return pthread_create(&s->thread, NULL, accept_thread, s);
}

static void server_stop(server *s) {
    atomic_store(&s->stop, 1);
    pthread_join(s->thread, NULL);
    for (int waited = 0; atomic_load(&s->connections) && waited < 5000; waited += 10) sleep_ms(10);
    close(s->listener);
    if (s->tls) SSL_CTX_free(s->tls);
}

/* ---- Helpers ---- */

static server plain, second, secure;
static char base[64], base_tls[64];

static tube_js_http_response *wait_one(tube_js_http *client, int limit_ms) {
    uint64_t deadline = tube_js_monotonic_ms() + (uint64_t)limit_ms;
    while (tube_js_monotonic_ms() < deadline) {
        tube_js_http_poll(client, 50);
        tube_js_http_response *response = tube_js_http_take(client);
        if (response) return response;
    }
    return NULL;
}

static tube_js_http_response *go(tube_js_http *client, const tube_js_http_request *request) {
    uint32_t id = 0;
    int error = tube_js_http_start(client, request, &id);
    CHECK(error == TUBE_JS_HTTP_OK);
    if (error != TUBE_JS_HTTP_OK) return NULL;
    CHECK(id != 0);
    tube_js_http_response *response = wait_one(client, 20000);
    CHECK(response != NULL);
    if (response) CHECK(response->id == id);
    return response;
}

static tube_js_http_response *get(tube_js_http *client, const char *origin, const char *path) {
    char url[256];
    snprintf(url, sizeof url, "%s%s", origin, path);
    tube_js_http_request request = {.url = url};
    return go(client, &request);
}

static const char *header_of(const tube_js_http_response *response, const char *name) {
    for (size_t i = 0; i < response->header_count; i++)
        if (!strcasecmp(response->headers[i].name, name)) return response->headers[i].value;
    return NULL;
}

/* For /echo answers: the request head the server saw, and the body after it. */
static int echoed(const tube_js_http_response *response, const char *needle) {
    return response && response->error == TUBE_JS_HTTP_OK && strcasestr((const char *)response->body, needle) != NULL;
}

static int echoed_body_is(const tube_js_http_response *response, const void *body, size_t length) {
    if (!response || response->error != TUBE_JS_HTTP_OK) return 0;
    const char *split = strstr((const char *)response->body, "\r\n\r\n");
    if (!split) return 0;
    size_t offset = (size_t)(split + 4 - (const char *)response->body);
    return response->body_length - offset == length && !memcmp(response->body + offset, body, length);
}

static void hex(const unsigned char *bytes, size_t length, char *output) {
    for (size_t i = 0; i < length; i++) sprintf(output + 2 * i, "%02x", bytes[i]);
}

/* ---- Hashes, random, clocks, timers ---- */

static void test_hashes(void) {
    static const char two_blocks[] = "abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq";
    unsigned char digest[32];
    char text[65];
    tube_js_sha1_digest("abc", 3, digest); hex(digest, 20, text);
    CHECK(!strcmp(text, "a9993e364706816aba3e25717850c26c9cd0d89d"));
    tube_js_sha1_digest("", 0, digest); hex(digest, 20, text);
    CHECK(!strcmp(text, "da39a3ee5e6b4b0d3255bfef95601890afd80709"));
    tube_js_sha1_digest(two_blocks, sizeof two_blocks - 1, digest); hex(digest, 20, text);
    CHECK(!strcmp(text, "84983e441c3bd26ebaae4aa1f95129e5e54670f1"));
    tube_js_sha256_digest("abc", 3, digest); hex(digest, 32, text);
    CHECK(!strcmp(text, "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"));
    tube_js_sha256_digest("", 0, digest); hex(digest, 32, text);
    CHECK(!strcmp(text, "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"));
    tube_js_sha256_digest(two_blocks, sizeof two_blocks - 1, digest); hex(digest, 32, text);
    CHECK(!strcmp(text, "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"));

    /* One million 'a', fed in pieces of every size up to 131 bytes. */
    static char block[131];
    memset(block, 'a', sizeof block);
    tube_js_sha1 one;
    tube_js_sha256 two;
    tube_js_sha1_init(&one);
    tube_js_sha256_init(&two);
    size_t left = 1000000, piece = 1;
    while (left) {
        size_t take = piece < left ? piece : left;
        tube_js_sha1_update(&one, block, take);
        tube_js_sha256_update(&two, block, take);
        left -= take;
        piece = piece % sizeof block + 1;
    }
    tube_js_sha1_final(&one, digest); hex(digest, 20, text);
    CHECK(!strcmp(text, "34aa973cd4c4daa4f61eeb2bdbad27316534016f"));
    tube_js_sha256_final(&two, digest); hex(digest, 32, text);
    CHECK(!strcmp(text, "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0"));

    /* Lengths around the padding boundary: streaming equals one shot. */
    for (size_t length = 50; length <= 70; length++) {
        unsigned char whole[32], parts[32];
        tube_js_sha256_digest(block, length, whole);
        tube_js_sha256_init(&two);
        tube_js_sha256_update(&two, block, 7);
        tube_js_sha256_update(&two, block + 7, length - 7);
        tube_js_sha256_final(&two, parts);
        CHECK(!memcmp(whole, parts, 32));
        tube_js_sha1_digest(block, length, whole);
        tube_js_sha1_init(&one);
        tube_js_sha1_update(&one, block, 49);
        tube_js_sha1_update(&one, block + 49, length - 49);
        tube_js_sha1_final(&one, parts);
        CHECK(!memcmp(whole, parts, 20));
    }
}

static void test_random_and_clocks(void) {
    unsigned char a[32] = {0}, b[32] = {0}, zero[32] = {0};
    CHECK(tube_js_random_bytes(a, sizeof a) == 0);
    CHECK(tube_js_random_bytes(b, sizeof b) == 0);
    CHECK(memcmp(a, zero, sizeof a) && memcmp(b, zero, sizeof b) && memcmp(a, b, sizeof a));
    CHECK(tube_js_random_bytes(a, 0) == 0);
    CHECK(tube_js_random_bytes(NULL, 0) == 0);
    CHECK(tube_js_random_bytes(NULL, 4) == -1);
    static unsigned char large[100000];
    CHECK(tube_js_random_bytes(large, sizeof large) == 0);
    int bits = 0;
    for (size_t i = 0; i < sizeof large; i++) bits += __builtin_popcount(large[i]);
    CHECK(bits > 390000 && bits < 410000);   /* 400000 expected; 30 standard deviations of room */

    uint64_t first = tube_js_monotonic_ms(), first_ns = tube_js_monotonic_ns();
    sleep_ms(30);
    uint64_t second = tube_js_monotonic_ms();
    CHECK(first > 0 && second >= first + 25 && second < first + 2000);
    CHECK(tube_js_monotonic_ns() > first_ns);
    int64_t wall = tube_js_wall_ms(), reference = (int64_t)time(NULL) * 1000;
    CHECK(wall > reference - 2000 && wall < reference + 2000);
}

static void test_timers(void) {
    tube_js_timers *timers = tube_js_timers_new();
    CHECK(timers != NULL);
    CHECK(tube_js_timers_next_delay(timers, 0) == -1);
    CHECK(tube_js_timers_pop_due(timers, 1000) == 0);
    uint32_t late = tube_js_timers_add(timers, 1000, 50, 0);
    uint32_t early = tube_js_timers_add(timers, 1000, 10, 0);
    uint32_t tie = tube_js_timers_add(timers, 1000, 10, 0);
    uint32_t every = tube_js_timers_add(timers, 1000, 20, 20);
    CHECK(late && early && tie && every && late != early && early != tie && tie != every);
    CHECK(tube_js_timers_count(timers) == 4);
    CHECK(tube_js_timers_next_delay(timers, 1000) == 10);
    CHECK(tube_js_timers_pop_due(timers, 1009) == 0);
    CHECK(tube_js_timers_pop_due(timers, 1010) == early);   /* same deadline: armed first, runs first */
    CHECK(tube_js_timers_pop_due(timers, 1010) == tie);
    CHECK(tube_js_timers_pop_due(timers, 1010) == 0);
    CHECK(tube_js_timers_next_delay(timers, 1015) == 5);
    CHECK(tube_js_timers_pop_due(timers, 1100) == every);   /* due at 1020, before `late` at 1050 */
    CHECK(tube_js_timers_pop_due(timers, 1100) == late);
    CHECK(tube_js_timers_pop_due(timers, 1100) == 0);        /* `every` re-armed from 1100, not from 1020 */
    CHECK(tube_js_timers_next_delay(timers, 1100) == 20);
    CHECK(tube_js_timers_pop_due(timers, 1120) == every);
    CHECK(tube_js_timers_cancel(timers, every) == 1);
    CHECK(tube_js_timers_cancel(timers, every) == 0);
    CHECK(tube_js_timers_cancel(timers, late) == 0);         /* a one-shot timer is gone once popped */
    CHECK(tube_js_timers_count(timers) == 0);
    uint32_t zero = tube_js_timers_add(timers, 5, 0, 0);
    CHECK(tube_js_timers_next_delay(timers, 5) == 0 && tube_js_timers_pop_due(timers, 5) == zero);
    uint32_t far = tube_js_timers_add(timers, 5, UINT64_MAX, 0);
    CHECK(far && tube_js_timers_next_delay(timers, 6) == 0x7fffffff);
    int added = 0;
    while (tube_js_timers_add(timers, 0, 1000, 0)) added++;   /* the limit holds */
    CHECK(added == 4095);
    tube_js_timers_free(timers);
    tube_js_timers_free(NULL);
}

/* ---- HTTP ---- */

static void test_basics(tube_js_http *client) {
    tube_js_http_response *r = get(client, base, "/hello");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 200 && !*r->error_text);
        CHECK(r->body_length == 5 && !memcmp(r->body, "hello", 5) && r->body[5] == 0);
        CHECK(header_of(r, "x-test") && !strcmp(header_of(r, "x-test"), "yes"));
        CHECK(header_of(r, "X-Two") && !strcmp(header_of(r, "X-Two"), "spaced value"));
        CHECK(header_of(r, "content-length") && !strcmp(header_of(r, "content-length"), "5"));
        CHECK(header_of(r, "absent") == NULL);
        CHECK(!r->redirected && strstr(r->url, "/hello"));
        tube_js_http_response_free(r);
    }
    r = get(client, base, "/missing");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 404 && r->body_length == 9);
        tube_js_http_response_free(r);
    }
    r = get(client, base, "/empty");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 204 && r->body_length == 0 && r->body && !r->body[0]);
        tube_js_http_response_free(r);
    }
    char url[128];
    snprintf(url, sizeof url, "%s/hello", base);
    tube_js_http_request head = {.method = "head", .url = url};
    r = go(client, &head);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 200 && r->body_length == 0);
        tube_js_http_response_free(r);
    }
    r = get(client, base, "/gzip");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->body_length == sizeof gzip_text - 1 &&
              !memcmp(r->body, gzip_text, sizeof gzip_text - 1));
        tube_js_http_response_free(r);
    }
}

static void test_request_shape(tube_js_http *client) {
    char url[128];
    snprintf(url, sizeof url, "%s/echo", base);
    static const unsigned char binary[] = {'a', 0, 'b', 0xff, '\r', '\n', 0, 'z'};
    tube_js_http_header headers[] = {{"Content-Type", "application/x-protobuf"}, {"X-Goog-Visitor-Id", "abc=="},
                                     {"X-Empty", ""}, {"Host", "evil.example"}, {"Accept-Encoding", "identity"},
                                     {"Content-Length", "999"}, {"User-Agent", "Mine/1"}};
    tube_js_http_request post = {.method = "post", .url = url, .headers = headers,
                                 .header_count = sizeof headers / sizeof *headers, .body = binary,
                                 .body_length = sizeof binary};
    tube_js_http_response *r = go(client, &post);
    if (r) {
        CHECK(echoed(r, "POST /echo HTTP/1.1\r\n"));
        CHECK(echoed(r, "\r\nContent-Type: application/x-protobuf\r\n"));
        CHECK(echoed(r, "\r\nX-Goog-Visitor-Id: abc==\r\n"));
        CHECK(echoed(r, "\r\nX-Empty:\r\n"));
        CHECK(echoed(r, "\r\nUser-Agent: Mine/1\r\n") && !echoed(r, "TubeTest"));
        CHECK(echoed(r, "\r\nContent-Length: 8\r\n") && !echoed(r, "999"));
        CHECK(echoed(r, "\r\nHost: 127.0.0.1:") && !echoed(r, "evil.example"));
        CHECK(echoed(r, "\r\nAccept-Encoding: ") && echoed(r, "gzip") && !echoed(r, "identity"));
        CHECK(!echoed(r, "\r\nExpect:") && !echoed(r, "\r\nCookie:"));
        CHECK(echoed_body_is(r, binary, sizeof binary));
        tube_js_http_response_free(r);
    }
    /* A body with no type from the caller goes out with no type at all. */
    tube_js_http_request bare = {.method = "POST", .url = url, .body = "x=1", .body_length = 3};
    r = go(client, &bare);
    if (r) {
        CHECK(echoed(r, "POST /echo") && !echoed(r, "Content-Type") && echoed(r, "\r\nUser-Agent: TubeTest/1\r\n"));
        CHECK(echoed_body_is(r, "x=1", 3));
        tube_js_http_response_free(r);
    }
    /* POST without a body still says how long its body is. */
    tube_js_http_request empty = {.method = "POST", .url = url};
    r = go(client, &empty);
    if (r) {
        CHECK(echoed(r, "POST /echo") && echoed(r, "\r\nContent-Length: 0\r\n"));
        tube_js_http_response_free(r);
    }
    tube_js_http_request remove = {.method = "delete", .url = url};
    r = go(client, &remove);
    if (r) {
        CHECK(echoed(r, "DELETE /echo HTTP/1.1"));
        tube_js_http_response_free(r);
    }
    tube_js_http_request patch = {.method = "PATCH", .url = url, .body = "{}", .body_length = 2};
    r = go(client, &patch);
    if (r) {
        CHECK(echoed(r, "PATCH /echo HTTP/1.1") && echoed_body_is(r, "{}", 2));
        tube_js_http_response_free(r);
    }

    uint32_t id = 7;
    tube_js_http_header injected[] = {{"X-A", "one\r\nX-Injected: yes"}};
    tube_js_http_request bad = {.url = url, .headers = injected, .header_count = 1};
    CHECK(tube_js_http_start(client, &bad, &id) == TUBE_JS_HTTP_INVALID && id == 0);
    tube_js_http_header bad_name[] = {{"X A", "v"}};
    bad.headers = bad_name;
    CHECK(tube_js_http_start(client, &bad, &id) == TUBE_JS_HTTP_INVALID);
    tube_js_http_request scheme = {.url = "ftp://127.0.0.1/file"};
    CHECK(tube_js_http_start(client, &scheme, &id) == TUBE_JS_HTTP_INVALID);
    tube_js_http_request file = {.url = "file:///etc/hostname"};
    CHECK(tube_js_http_start(client, &file, &id) == TUBE_JS_HTTP_INVALID);
    tube_js_http_request trace = {.method = "TRACE", .url = url};
    CHECK(tube_js_http_start(client, &trace, &id) == TUBE_JS_HTTP_INVALID);
    tube_js_http_request get_body = {.method = "GET", .url = url, .body = "x", .body_length = 1};
    CHECK(tube_js_http_start(client, &get_body, &id) == TUBE_JS_HTTP_INVALID);
    tube_js_http_request mode = {.url = url, .redirect = 9};
    CHECK(tube_js_http_start(client, &mode, &id) == TUBE_JS_HTTP_INVALID);
    CHECK(tube_js_http_start(client, NULL, &id) == TUBE_JS_HTTP_INVALID);
    CHECK(tube_js_http_start(NULL, &trace, &id) == TUBE_JS_HTTP_INVALID);
    CHECK(tube_js_http_active(client) == 0 && tube_js_http_take(client) == NULL);
}

static void test_redirects(tube_js_http *client) {
    char url[128];
    tube_js_http_response *r = get(client, base, "/redirect/3");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 200 && r->redirected);
        CHECK(r->body_length == 6 && !memcmp(r->body, "landed", 6) && strstr(r->url, "/redirect/0"));
        CHECK(header_of(r, "location") == NULL);   /* only the final answer's headers */
        tube_js_http_response_free(r);
    }
    r = get(client, base, "/loop");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_REDIRECT && r->status == 0 && r->body_length == 0 && *r->error_text);
        tube_js_http_response_free(r);
    }
    r = get(client, base, "/elsewhere");   /* a redirect out of http(s) is refused, not followed */
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_REDIRECT);
        tube_js_http_response_free(r);
    }
    r = get(client, base, "/nowhere");     /* 302 without Location is just an answer */
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 302 && r->body_length == 11);
        tube_js_http_response_free(r);
    }
    snprintf(url, sizeof url, "%s/r302", base);
    tube_js_http_request manual = {.url = url, .redirect = TUBE_JS_HTTP_REDIRECT_MANUAL};
    r = go(client, &manual);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 302 && !r->redirected);
        CHECK(header_of(r, "location") && !strcmp(header_of(r, "location"), "/echo"));
        tube_js_http_response_free(r);
    }
    tube_js_http_request refuse = {.url = url, .redirect = TUBE_JS_HTTP_REDIRECT_ERROR};
    r = go(client, &refuse);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_REDIRECT);
        tube_js_http_response_free(r);
    }

    /* Method and body across redirects, as fetch defines them. */
    static const struct {
        const char *path, *method, *expect;
        int keeps_body;
    } cases[] = {{"/r301", "POST", "GET /echo", 0},  {"/r302", "POST", "GET /echo", 0},
                 {"/r303", "POST", "GET /echo", 0},  {"/r303", "PUT", "GET /echo", 0},
                 {"/r307", "POST", "POST /echo", 1}, {"/r308", "POST", "POST /echo", 1},
                 {"/r301", "PUT", "PUT /echo", 1},   {"/r302", "PUT", "PUT /echo", 1},
                 {"/r307", "PUT", "PUT /echo", 1}};
    for (size_t i = 0; i < sizeof cases / sizeof *cases; i++) {
        snprintf(url, sizeof url, "%s%s", base, cases[i].path);
        tube_js_http_header headers[] = {{"Content-Type", "text/x-probe"}, {"Authorization", "Bearer same-origin"}};
        tube_js_http_request request = {.method = cases[i].method, .url = url, .headers = headers,
                                        .header_count = 2, .body = "payload", .body_length = 7};
        r = go(client, &request);
        if (!r) continue;
        CHECK(r->redirected && echoed(r, cases[i].expect));
        CHECK(echoed(r, "Bearer same-origin"));   /* same origin: the credential stays */
        if (cases[i].keeps_body) CHECK(echoed_body_is(r, "payload", 7) && echoed(r, "text/x-probe"));
        else CHECK(echoed_body_is(r, "", 0) && !echoed(r, "text/x-probe") && !echoed(r, "Content-Length"));
        tube_js_http_response_free(r);
    }

    /* Another origin (same address, other port): Authorization is dropped, the rest stays. */
    snprintf(url, sizeof url, "%s/cross", base);
    tube_js_http_header headers[] = {{"Authorization", "Bearer secret"}, {"X-Keep", "kept"}};
    tube_js_http_request cross = {.url = url, .headers = headers, .header_count = 2};
    r = go(client, &cross);
    if (r) {
        char host[64];
        snprintf(host, sizeof host, "Host: 127.0.0.1:%d", second.port);
        CHECK(r->redirected && echoed(r, host) && echoed(r, "X-Keep: kept"));
        CHECK(!echoed(r, "Authorization") && !echoed(r, "secret"));
        tube_js_http_response_free(r);
    }

    tube_js_http_config limited = {.max_redirects = 2};
    tube_js_http *small = tube_js_http_new(&limited);
    r = get(small, base, "/redirect/2");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 200);
        tube_js_http_response_free(r);
    }
    r = get(small, base, "/redirect/3");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_REDIRECT);
        tube_js_http_response_free(r);
    }
    tube_js_http_free(small);
}

static void test_bounds(tube_js_http *client) {
    char url[128];
    snprintf(url, sizeof url, "%s/big/4096", base);
    tube_js_http_request exact = {.url = url, .max_response_bytes = 4096};
    tube_js_http_response *r = go(client, &exact);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->body_length == 4096);
        tube_js_http_response_free(r);
    }
    snprintf(url, sizeof url, "%s/big/4097", base);
    tube_js_http_request over = {.url = url, .max_response_bytes = 4096};
    r = go(client, &over);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_TOO_LARGE && r->body_length == 0 && r->status == 0);
        tube_js_http_response_free(r);
    }
    snprintf(url, sizeof url, "%s/big/3000000", base);
    tube_js_http_request large = {.url = url};
    r = go(client, &large);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->body_length == 3000000 && r->body[2999999] == 'x');
        tube_js_http_response_free(r);
    }
    tube_js_http_request small_default = {.url = url};
    tube_js_http_config tight = {.max_response_bytes = 1000};
    tube_js_http *bounded = tube_js_http_new(&tight);
    r = go(bounded, &small_default);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_TOO_LARGE);
        tube_js_http_response_free(r);
    }
    tube_js_http_free(bounded);
    r = get(client, base, "/manyheaders");   /* more header lines than an answer may carry */
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_TOO_LARGE);
        tube_js_http_response_free(r);
    }
    /* The gzip answer is bounded by its decoded size. */
    snprintf(url, sizeof url, "%s/gzip", base);
    tube_js_http_request squeezed = {.url = url, .max_response_bytes = sizeof gzip_bytes};
    r = go(client, &squeezed);
    if (r) {
        CHECK(sizeof gzip_bytes < sizeof gzip_text - 1 && r->error == TUBE_JS_HTTP_TOO_LARGE);
        tube_js_http_response_free(r);
    }
}

static void test_timeout_and_cancel(tube_js_http *client) {
    char url[128];
    snprintf(url, sizeof url, "%s/slow/5000", base);
    uint64_t start = tube_js_monotonic_ms();
    tube_js_http_request slow = {.url = url, .timeout_ms = 300};
    tube_js_http_response *r = go(client, &slow);
    if (r) {
        uint64_t took = tube_js_monotonic_ms() - start;
        CHECK(r->error == TUBE_JS_HTTP_TIMEOUT && took >= 250 && took < 2000);
        tube_js_http_response_free(r);
    }
    /* The time limit covers the redirects too. */
    snprintf(url, sizeof url, "%s/redirect/1", base);
    tube_js_http_request quick = {.url = url, .timeout_ms = 5000};
    r = go(client, &quick);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK);
        tube_js_http_response_free(r);
    }

    snprintf(url, sizeof url, "%s/slow/5000", base);
    tube_js_http_request waiting = {.url = url};
    uint32_t id = 0, other = 0;
    start = tube_js_monotonic_ms();
    CHECK(tube_js_http_start(client, &waiting, &id) == TUBE_JS_HTTP_OK);
    CHECK(tube_js_http_start(client, &waiting, &other) == TUBE_JS_HTTP_OK && other != id);
    for (int i = 0; i < 5; i++) CHECK(tube_js_http_poll(client, 30) == 0);
    CHECK(tube_js_http_active(client) == 2);
    CHECK(tube_js_http_cancel(client, id) == 1);
    CHECK(tube_js_http_cancel(client, id) == 0);          /* already complete */
    CHECK(tube_js_http_cancel(client, 999999) == 0);
    CHECK(tube_js_http_active(client) == 1);
    CHECK(tube_js_http_poll(client, 0) == 1);
    r = tube_js_http_take(client);
    CHECK(r && r->id == id && r->error == TUBE_JS_HTTP_ABORTED && r->status == 0);
    tube_js_http_response_free(r);
    CHECK(tube_js_http_cancel(client, other) == 1);
    r = tube_js_http_take(client);
    CHECK(r && r->id == other && r->error == TUBE_JS_HTTP_ABORTED);
    tube_js_http_response_free(r);
    CHECK(tube_js_monotonic_ms() - start < 2000 && tube_js_http_active(client) == 0);

    /* Nothing listens on port 1 of this machine. */
    tube_js_http_request refused = {.url = "http://127.0.0.1:1/"};
    r = go(client, &refused);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_CONNECT && *r->error_text);
        tube_js_http_response_free(r);
    }
}

static void test_concurrency(void) {
    tube_js_http_config config = {.max_requests = 12};
    tube_js_http *client = tube_js_http_new(&config);
    char url[128];
    enum { COUNT = 12 };
    uint32_t ids[COUNT + 1] = {0};
    int seen[COUNT] = {0};
    uint64_t start = tube_js_monotonic_ms();
    for (int i = 0; i < COUNT; i++) {
        snprintf(url, sizeof url, "%s/slow/%d", base, 300 + 10 * (i % 3));
        tube_js_http_request request = {.url = url};
        CHECK(tube_js_http_start(client, &request, &ids[i]) == TUBE_JS_HTTP_OK);
    }
    tube_js_http_request extra = {.url = url};
    CHECK(tube_js_http_start(client, &extra, &ids[COUNT]) == TUBE_JS_HTTP_BUSY && ids[COUNT] == 0);
    CHECK(tube_js_http_active(client) == COUNT);
    for (int done = 0; done < COUNT;) {
        tube_js_http_response *r = wait_one(client, 10000);
        CHECK(r != NULL);
        if (!r) break;
        CHECK(r->error == TUBE_JS_HTTP_OK && r->body_length == 4);
        for (int i = 0; i < COUNT; i++)
            if (ids[i] == r->id) seen[i]++;
        tube_js_http_response_free(r);
        done++;
    }
    uint64_t took = tube_js_monotonic_ms() - start;
    for (int i = 0; i < COUNT; i++) CHECK(seen[i] == 1);
    /* Twelve 0.3 s answers over six connections: two rounds, not twelve. */
    CHECK(took >= 600 && took < 2500);
    /* Room again once the answers were taken. */
    CHECK(tube_js_http_start(client, &extra, &ids[COUNT]) == TUBE_JS_HTTP_OK);
    /* Freed with a request in flight and an answer never taken. */
    snprintf(url, sizeof url, "%s/hello", base);
    tube_js_http_request quick = {.url = url};
    uint32_t id;
    CHECK(tube_js_http_start(client, &quick, &id) == TUBE_JS_HTTP_OK);
    for (int i = 0; i < 40 && tube_js_http_poll(client, 50) == 0; i++) continue;
    tube_js_http_response *kept = tube_js_http_take(client);
    CHECK(kept != NULL);
    tube_js_http_free(client);
    if (kept) {   /* an answer already taken outlives its client */
        CHECK(kept->error == TUBE_JS_HTTP_OK && kept->body_length == 5 && !memcmp(kept->body, "hello", 5));
        tube_js_http_response_free(kept);
    }
}

static void test_cookies(tube_js_http *client) {
    tube_js_http_response *r = get(client, base, "/hello");
    if (r) tube_js_http_response_free(r);
    r = get(client, base, "/echo");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && !echoed(r, "Cookie"));   /* no jar unless asked for */
        tube_js_http_response_free(r);
    }
    tube_js_http_config config = {.cookies = 1};
    tube_js_http *jar = tube_js_http_new(&config);
    r = get(jar, base, "/hello");
    if (r) tube_js_http_response_free(r);
    r = get(jar, base, "/echo");
    if (r) {
        CHECK(echoed(r, "\r\nCookie: sid=abc\r\n"));
        tube_js_http_response_free(r);
    }
    tube_js_http_free(jar);
}

static void *wake_thread(void *argument) {
    sleep_ms(150);
    CHECK(tube_js_http_wake(argument) == 0);
    return NULL;
}

static void test_wake(tube_js_http *client) {
    pthread_t thread;
    uint64_t start = tube_js_monotonic_ms();
    pthread_create(&thread, NULL, wake_thread, client);
    CHECK(tube_js_http_poll(client, 5000) == 0);   /* idle: only the wake ends this wait */
    uint64_t took = tube_js_monotonic_ms() - start;
    pthread_join(thread, NULL);
    CHECK(took >= 100 && took < 2000);
    start = tube_js_monotonic_ms();
    CHECK(tube_js_http_poll(client, 120) == 0);
    took = tube_js_monotonic_ms() - start;
    CHECK(took >= 100 && took < 1000);             /* and without one it waits its time */
}

/* The console's way of waiting: short slices, the transfers moved along
 * between them, and a wake seen without relying on the wake-up pipe. */
static void test_slices(void) {
    tube_js_http_config config = {.poll_slice_ms = 10};
    tube_js_http *client = tube_js_http_new(&config);
    char url[128];
    snprintf(url, sizeof url, "%s/slow/300", base);
    tube_js_http_request request = {.url = url};
    uint32_t id = 0;
    uint64_t start = tube_js_monotonic_ms();
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    CHECK(tube_js_http_poll(client, 5000) == 1);   /* one call returns when the answer is there */
    uint64_t took = tube_js_monotonic_ms() - start;
    CHECK(took >= 250 && took < 2000);
    tube_js_http_response *r = tube_js_http_take(client);
    CHECK(r && r->id == id && r->error == TUBE_JS_HTTP_OK && r->body_length == 4);
    tube_js_http_response_free(r);
    start = tube_js_monotonic_ms();
    CHECK(tube_js_http_poll(client, 120) == 0);
    took = tube_js_monotonic_ms() - start;
    CHECK(took >= 100 && took < 1000);
    pthread_t thread;
    start = tube_js_monotonic_ms();
    pthread_create(&thread, NULL, wake_thread, client);
    CHECK(tube_js_http_poll(client, 5000) == 0);
    took = tube_js_monotonic_ms() - start;
    pthread_join(thread, NULL);
    CHECK(took >= 100 && took < 2000);
    CHECK(tube_js_http_wake(client) == 0);         /* a wake before the wait ends that wait at once */
    start = tube_js_monotonic_ms();
    CHECK(tube_js_http_poll(client, 3000) == 0);
    CHECK(tube_js_monotonic_ms() - start < 1000);
    tube_js_http_free(client);
}

/* Streaming requests: the body arrives in pieces while the answer is still
 * open. `slice` is the console's way of waiting (0 = the desktop's). */
typedef struct stream_log {
    char text[4096];
    size_t length;
    int pieces, wrong;
    uint64_t first_ms, last_ms;
} stream_log;

/* Polls until the request completes or `limit_ms` passed, taking its pieces as they come. */
static tube_js_http_response *stream_run(tube_js_http *client, uint32_t id, int limit_ms, stream_log *log) {
    uint64_t start = tube_js_monotonic_ms();
    memset(log, 0, sizeof *log);
    while (tube_js_monotonic_ms() - start < (uint64_t)limit_ms) {
        tube_js_http_poll(client, 50);
        tube_js_http_chunk chunk;
        while (tube_js_http_take_chunk(client, &chunk)) {
            if (chunk.id != id || chunk.status != 200 || !chunk.length || log->length + chunk.length >= sizeof log->text) log->wrong++;
            else {
                memcpy(log->text + log->length, chunk.data, chunk.length);
                log->length += chunk.length;
            }
            log->last_ms = tube_js_monotonic_ms() - start;
            if (!log->pieces++) log->first_ms = log->last_ms;
        }
        tube_js_http_response *response = tube_js_http_take(client);
        if (response) return response;
    }
    return NULL;
}

static void test_streaming(const char *origin, const char *certificate, int slice) {
    tube_js_http_config config = {.ca_file = certificate, .poll_slice_ms = slice};
    tube_js_http *client = tube_js_http_new(&config);
    char url[160];
    uint32_t id = 0;
    stream_log log;

    /* Five pieces 100 ms apart: each is handed over when it arrives, long before
     * the answer ends, and the completed answer has no body left. */
    snprintf(url, sizeof url, "%s/stream/5/100", origin);
    tube_js_http_request request = {.url = url, .stream = 1, .timeout_ms = 3000};
    uint64_t start = tube_js_monotonic_ms();
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    tube_js_http_response *r = stream_run(client, id, 10000, &log);
    uint64_t took = tube_js_monotonic_ms() - start;
    CHECK(r && r->id == id && r->error == TUBE_JS_HTTP_OK && r->status == 200 && r->body_length == 0);
    CHECK(r && header_of(r, "Content-Type") && !strcmp(header_of(r, "Content-Type"), "text/plain"));
    CHECK(!log.wrong && log.length == 40 && !memcmp(log.text, "piece-0\npiece-1\npiece-2\npiece-3\npiece-4\n", 40));
    CHECK(log.pieces >= 4 && log.first_ms < 300 && log.last_ms >= 300 && took >= 450 && took < 5000);
    tube_js_http_response_free(r);

    /* The limit of a streaming request is its longest silence, not its length. */
    snprintf(url, sizeof url, "%s/stream/6/150", origin);
    request.timeout_ms = 500;
    start = tube_js_monotonic_ms();
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    r = stream_run(client, id, 10000, &log);
    CHECK(r && r->error == TUBE_JS_HTTP_OK && log.length == 48 && tube_js_monotonic_ms() - start >= 800);
    tube_js_http_response_free(r);

    /* A stream that goes silent ends as a timeout; what arrived before was delivered. */
    snprintf(url, sizeof url, "%s/stall/4000", origin);
    request.timeout_ms = 300;
    start = tube_js_monotonic_ms();
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    r = stream_run(client, id, 10000, &log);
    took = tube_js_monotonic_ms() - start;
    CHECK(r && r->id == id && r->error == TUBE_JS_HTTP_TIMEOUT && r->status == 0 && r->body_length == 0);
    CHECK(log.pieces == 1 && log.length == 6 && !memcmp(log.text, "first\n", 6) && took >= 250 && took < 2500);
    tube_js_http_response_free(r);

    /* Cancelled while open: nothing more arrives for it. */
    request.timeout_ms = 3000;
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    tube_js_http_chunk chunk;
    int got = 0;
    for (int i = 0; i < 100 && !(got = tube_js_http_take_chunk(client, &chunk)); i++) tube_js_http_poll(client, 50);
    CHECK(got && chunk.id == id && chunk.status == 200 && chunk.length == 6 && !memcmp(chunk.data, "first\n", 6));
    CHECK(!tube_js_http_take_chunk(client, &chunk) && tube_js_http_active(client) == 1);
    CHECK(tube_js_http_cancel(client, id) == 1 && tube_js_http_active(client) == 0);
    CHECK(tube_js_http_poll(client, 0) == 1 && !tube_js_http_take_chunk(client, &chunk));
    r = tube_js_http_take(client);
    CHECK(r && r->id == id && r->error == TUBE_JS_HTTP_ABORTED);
    tube_js_http_response_free(r);

    /* A piece that waits ends the wait at once; pieces nobody took are the completed answer's body. */
    snprintf(url, sizeof url, "%s/stream/3/150", origin);
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    for (int i = 0; i < 10; i++) {   /* the first piece is there, the answer is not over */
        sleep_ms(10);
        tube_js_http_poll(client, 0);
    }
    start = tube_js_monotonic_ms();
    CHECK(tube_js_http_poll(client, 2000) == 0 && tube_js_monotonic_ms() - start < 100);
    for (int i = 0; i < 500 && !tube_js_http_poll(client, 0); i++) sleep_ms(10);
    r = tube_js_http_take(client);
    CHECK(r && r->error == TUBE_JS_HTTP_OK && r->body_length == 24 && !memcmp(r->body, "piece-0\npiece-1\npiece-2\n", 24));
    tube_js_http_response_free(r);
    CHECK(!tube_js_http_take_chunk(client, &chunk));

    /* What waits to be taken is bounded. */
    snprintf(url, sizeof url, "%s/flood/200000", origin);
    request.max_response_bytes = 1000;
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    r = stream_run(client, id, 10000, &log);
    CHECK(r && r->error == TUBE_JS_HTTP_TOO_LARGE && r->body_length == 0 && log.length <= 1000);
    tube_js_http_response_free(r);
    request.max_response_bytes = 0;

    /* A redirect that is followed: only the final answer's body is the stream. */
    snprintf(url, sizeof url, "%s/stream-moved", origin);
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    r = stream_run(client, id, 10000, &log);
    CHECK(r && r->error == TUBE_JS_HTTP_OK && r->redirected && r->status == 200 && !log.wrong && log.length == 24 && !memcmp(log.text, "piece-0\n", 8));
    tube_js_http_response_free(r);
    /* Not followed, or refused: the pieces carry that answer's status. */
    request.redirect = TUBE_JS_HTTP_REDIRECT_MANUAL;
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    got = 0;
    for (int i = 0; i < 100 && !(got = tube_js_http_take_chunk(client, &chunk)); i++) tube_js_http_poll(client, 50);
    CHECK(got && chunk.status == 302 && chunk.length == 5 && !memcmp(chunk.data, "moved", 5));
    r = wait_one(client, 10000);
    CHECK(r && r->error == TUBE_JS_HTTP_OK && r->status == 302 && r->body_length == 0);
    tube_js_http_response_free(r);
    request.redirect = TUBE_JS_HTTP_REDIRECT_FOLLOW;
    snprintf(url, sizeof url, "%s/stream-refused", origin);
    CHECK(tube_js_http_start(client, &request, &id) == TUBE_JS_HTTP_OK);
    got = 0;
    for (int i = 0; i < 100 && !(got = tube_js_http_take_chunk(client, &chunk)); i++) tube_js_http_poll(client, 50);
    CHECK(got && chunk.status == 503 && chunk.length == 7);
    r = wait_one(client, 10000);
    CHECK(r && r->error == TUBE_JS_HTTP_OK && r->status == 503);
    tube_js_http_response_free(r);

    /* An ordinary request beside an open stream is not held up, and keeps its own rules. */
    snprintf(url, sizeof url, "%s/stall/4000", origin);
    uint32_t open_id = 0;
    CHECK(tube_js_http_start(client, &request, &open_id) == TUBE_JS_HTTP_OK);
    char other[160];
    snprintf(other, sizeof other, "%s/hello", origin);
    tube_js_http_request plain_request = {.url = other};
    CHECK(tube_js_http_start(client, &plain_request, &id) == TUBE_JS_HTTP_OK);
    r = stream_run(client, open_id, 5000, &log);
    CHECK(r && r->id == id && r->error == TUBE_JS_HTTP_OK && r->body_length == 5 && !memcmp(r->body, "hello", 5));
    tube_js_http_response_free(r);
    CHECK(tube_js_http_active(client) == 1);
    /* Freed with the stream still open and a piece possibly waiting. */
    tube_js_http_free(client);
}

static char *read_file(const char *path, size_t *length) {
    FILE *file = fopen(path, "rb");
    if (!file) return NULL;
    char *data = malloc(1 << 16);
    *length = data ? fread(data, 1, 1 << 16, file) : 0;
    fclose(file);
    return data;
}

static void test_tls(const char *certificate, const char *other) {
    char url[128];
    /* The server's certificate names the address 127.0.0.1 and nothing else. */
    tube_js_http_config trusted = {.ca_file = certificate};
    tube_js_http *client = tube_js_http_new(&trusted);
    tube_js_http_response *r = get(client, base_tls, "/hello");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK && r->status == 200 && r->body_length == 5);
        tube_js_http_response_free(r);
    }
    snprintf(url, sizeof url, "%s/echo", base_tls);
    tube_js_http_request post = {.method = "POST", .url = url, .body = "tls body", .body_length = 8};
    r = go(client, &post);
    if (r) {
        CHECK(echoed_body_is(r, "tls body", 8));
        tube_js_http_response_free(r);
    }
    /* Right root, wrong name: the certificate is not for "localhost". */
    snprintf(url, sizeof url, "https://localhost:%d/hello", secure.port);
    tube_js_http_request wrong_name = {.url = url};
    r = go(client, &wrong_name);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_TLS && r->status == 0 && r->body_length == 0);
        tube_js_http_response_free(r);
    }
    tube_js_http_free(client);

    /* The machine's own roots do not include the test certificate. */
    client = tube_js_http_new(NULL);
    r = get(client, base_tls, "/hello");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_TLS);
        tube_js_http_response_free(r);
    }
    /* TLS spoken to a server that does not speak it. */
    snprintf(url, sizeof url, "https://127.0.0.1:%d/hello", plain.port);
    tube_js_http_request not_tls = {.url = url, .timeout_ms = 3000};
    r = go(client, &not_tls);
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_TLS || r->error == TUBE_JS_HTTP_NETWORK || r->error == TUBE_JS_HTTP_TIMEOUT);
        CHECK(r->error != TUBE_JS_HTTP_OK);
        tube_js_http_response_free(r);
    }
    tube_js_http_free(client);

    /* The roots handed over in memory instead of as a file: the right one works,
     * and then it alone counts - a wrong root or bytes that are no certificate
     * fail the request even though ca_file names the right one. */
    size_t right_length = 0, other_length = 0;
    char *right = read_file(certificate, &right_length), *wrong = read_file(other, &other_length);
    CHECK(right && wrong);
    if (right && wrong) {
        static const char garbage[] = "this is not a certificate";
        const struct {
            const void *data;
            size_t length;
            int expect;
        } blobs[] = {{right, right_length, TUBE_JS_HTTP_OK}, {wrong, other_length, TUBE_JS_HTTP_TLS},
                     {garbage, sizeof garbage - 1, TUBE_JS_HTTP_TLS}};
        for (size_t i = 0; i < sizeof blobs / sizeof *blobs; i++) {
            tube_js_http_config memory = {.ca_file = certificate, .ca_data = blobs[i].data, .ca_length = blobs[i].length};
            client = tube_js_http_new(&memory);
            if (i == 0) memset(right, 'x', right_length);   /* the client keeps its own copy */
            r = get(client, base_tls, "/hello");
            if (r) {
                CHECK(r->error == blobs[i].expect && (r->error != TUBE_JS_HTTP_OK || r->body_length == 5));
                tube_js_http_response_free(r);
            }
            tube_js_http_free(client);
        }
    }
    free(right);
    free(wrong);

    /* A root file that is not there fails the request; it never means "trust anyone". */
    tube_js_http_config missing = {.ca_file = "/nonexistent/tube-js-roots.pem"};
    client = tube_js_http_new(&missing);
    r = get(client, base_tls, "/hello");
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_TLS && r->body_length == 0);
        tube_js_http_response_free(r);
    }
    r = get(client, base, "/hello");   /* plain http does not need the file */
    if (r) {
        CHECK(r->error == TUBE_JS_HTTP_OK);
        tube_js_http_response_free(r);
    }
    tube_js_http_free(client);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "usage: test_bindings <certificate.pem> <key.pem> <unrelated-certificate.pem>\n");
        return 2;
    }
    signal(SIGPIPE, SIG_IGN);
    test_hashes();
    test_random_and_clocks();
    test_timers();

    if (server_start(&plain, NULL, NULL) || server_start(&second, NULL, NULL) || server_start(&secure, argv[1], argv[2])) {
        fprintf(stderr, "the test servers did not start\n");
        return 2;
    }
    plain.other_port = second.port;
    snprintf(base, sizeof base, "http://127.0.0.1:%d", plain.port);
    snprintf(base_tls, sizeof base_tls, "https://127.0.0.1:%d", secure.port);

    tube_js_http_config config = {.user_agent = "TubeTest/1"};
    tube_js_http *client = tube_js_http_new(&config);
    CHECK(client != NULL && strstr(tube_js_http_backend(), "libcurl/") != NULL);
    test_basics(client);
    test_request_shape(client);
    test_redirects(client);
    test_bounds(client);
    test_timeout_and_cancel(client);
    test_cookies(client);
    test_wake(client);
    tube_js_http_free(client);
    tube_js_http_free(NULL);
    tube_js_http_response_free(NULL);
    test_concurrency();
    test_slices();
    test_tls(argv[1], argv[3]);
    test_streaming(base, NULL, 0);
    test_streaming(base, NULL, 10);
    test_streaming(base_tls, argv[1], 10);
    CHECK(!strcmp(tube_js_http_error_name(TUBE_JS_HTTP_TLS), "TLS failure") && *tube_js_http_error_name(99));

    int served = atomic_load(&plain.served) + atomic_load(&second.served) + atomic_load(&secure.served);
    server_stop(&plain);
    server_stop(&second);
    server_stop(&secure);
    printf("test_bindings: %d checks, %d failures, %d requests served on 127.0.0.1 (%s)\n", checks, failures, served,
           tube_js_http_backend());
    return failures ? 1 : 0;
}
